     AND ((table_name = 'orders' AND column_name = 'cross_dock_date') OR (table_name = 'order_stops' AND column_name = 'datetime')
       OR (table_name = 'ramp' AND column_name = 'plan_date') OR (table_name = 'ramp' AND column_name = 'postponed_to'));
