    to_regprocedure('public.order_cd_stop_follow()') IS NOT NULL, to_regprocedure('public.ramp_follows_stop()') IS NOT NULL,
    (SELECT red_value FROM monitoring.checks WHERE id = 'B-54'));
  RAISE EXCEPTION 'DRY RUN 069 finished - EVERYTHING UNDONE, nothing kept. The block ran to its end  ||  %', res;
END
